#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32
#define BLOCK_ROWS 8

__global__ void matmul_kernel_reg_blocking(const float* a, const float* b, float* out, int N) {
    __shared__ float a_tile[TILE_DIM][TILE_DIM];
    __shared__ float b_tile[TILE_DIM][TILE_DIM];

    int row = blockIdx.y * TILE_DIM + threadIdx.y;
    int col = blockIdx.x * TILE_DIM + threadIdx.x;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int thread_row = ty;

    float acc[BLOCK_ROWS] = {0.0f};

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tiles into shared memory
        if ( (blockIdx.y * TILE_DIM + ty) < N && (t * TILE_DIM + tx) < N)
             a_tile[ty][tx] = a[(blockIdx.y * TILE_DIM + ty) * N + t * TILE_DIM + tx];
        else
            a_tile[ty][tx] = 0.0;

        if ( (t * TILE_DIM + ty) < N && (blockIdx.x * TILE_DIM + tx) < N)
            b_tile[ty][tx] = b[(t * TILE_DIM + ty) * N + (blockIdx.x * TILE_DIM + tx)];
        else
            b_tile[ty][tx] = 0.0;

        __syncthreads();

        for (int k = 0; k < TILE_DIM; k++) {
            float b_val = b_tile[k][tx];
            for (int i = 0; i < BLOCK_ROWS; i++) {
                 acc[i] += a_tile[thread_row + i * (TILE_DIM/BLOCK_ROWS)][k] * b_val;
            }
        }
        __syncthreads();
    }

    for (int i = 0; i < BLOCK_ROWS; i++) {
        int cur_row = blockIdx.y * TILE_DIM + thread_row + i * (TILE_DIM/BLOCK_ROWS);
        if(cur_row < N && col < N)
